function perfectpixel_checkout_upload_field() {
	$ajax_url = admin_url( 'admin-ajax.php' );
	$nonce    = wp_create_nonce( 'perfectpixel_checkout_upload' );
	?>
	<p class="form-row form-row-wide" id="perfectpixel-upload-row">
		<label for="perfectpixel-upload"><?php esc_html_e( 'Upload a file (PDF, max 5 MB)', 'woocommerce' ); ?></label>
		<input type="file" id="perfectpixel-upload" accept="application/pdf">
		<input type="hidden" name="perfectpixel_upload_url" id="perfectpixel-upload-url" value="">
		<span id="perfectpixel-upload-status" aria-live="polite"></span>
	</p>
	<script>
	( function () {
		var input = document.getElementById( 'perfectpixel-upload' );
		var status = document.getElementById( 'perfectpixel-upload-status' );
		input.addEventListener( 'change', function () {
			if ( ! input.files.length ) {
				return;
			}
			var data = new FormData();
			data.append( 'action', 'perfectpixel_checkout_upload' );
			data.append( 'nonce', <?php echo wp_json_encode( $nonce ); ?> );
			data.append( 'file', input.files[0] );
			status.textContent = '…';
			fetch( <?php echo wp_json_encode( $ajax_url ); ?>, { method: 'POST', body: data, credentials: 'same-origin' } )
				.then( function ( r ) { return r.json(); } )
				.then( function ( res ) {
					if ( res.success ) {
						document.getElementById( 'perfectpixel-upload-url' ).value = res.data.url;
						status.textContent = ' ✓';
					} else {
						input.value = '';
						status.textContent = ' ' + ( res.data && res.data.message ? res.data.message : 'Upload failed' );
					}
				} )
				.catch( function () { status.textContent = ' Upload failed'; } );
		} );
	} )();
	</script>
	<?php
}

function perfectpixel_checkout_upload_handler() {
	check_ajax_referer( 'perfectpixel_checkout_upload', 'nonce' );

	if ( ! function_exists( 'WC' ) || ! WC()->cart || WC()->cart->is_empty() || ! WC()->session ) {
		wp_send_json_error( array( 'message' => 'Your cart is empty.' ), 400 );
	}

	$count = (int) WC()->session->get( 'perfectpixel_upload_count', 0 );
	if ( $count >= 5 ) {
		wp_send_json_error( array( 'message' => 'Too many uploads.' ), 429 );
	}

	if ( empty( $_FILES['file'] ) || UPLOAD_ERR_OK !== (int) $_FILES['file']['error'] ) { // phpcs:ignore WordPress.Security.ValidatedSanitizedInput
		wp_send_json_error( array( 'message' => 'No file received.' ), 400 );
	}
	if ( (int) $_FILES['file']['size'] > 5 * MB_IN_BYTES ) {
		wp_send_json_error( array( 'message' => 'The file is larger than 5 MB.' ), 400 );
	}

	require_once ABSPATH . 'wp-admin/includes/file.php';
	$result = wp_handle_upload(
		$_FILES['file'], // phpcs:ignore WordPress.Security.ValidatedSanitizedInput
		array(
			'test_form' => false,
			'mimes'     => array( 'pdf' => 'application/pdf' ),
		)
	);

	if ( isset( $result['error'] ) ) {
		wp_send_json_error( array( 'message' => $result['error'] ), 400 );
	}

	WC()->session->set( 'perfectpixel_upload_count', $count + 1 );
	$uploads   = (array) WC()->session->get( 'perfectpixel_upload_urls', array() );
	$uploads[] = $result['url'];
	WC()->session->set( 'perfectpixel_upload_urls', $uploads );

	wp_send_json_success( array( 'url' => $result['url'] ) );
}

function perfectpixel_checkout_upload_save( $order, $data ) {
	$url = isset( $_POST['perfectpixel_upload_url'] ) ? esc_url_raw( wp_unslash( $_POST['perfectpixel_upload_url'] ) ) : ''; // phpcs:ignore WordPress.Security.NonceVerification
	// Accept only files uploaded in this session.
	$allowed = WC()->session ? (array) WC()->session->get( 'perfectpixel_upload_urls', array() ) : array();
	if ( $url && in_array( $url, $allowed, true ) ) {
		$order->update_meta_data( '_perfectpixel_upload_url', $url );
	}
}

function perfectpixel_checkout_upload_admin( $order ) {
	$url = $order->get_meta( '_perfectpixel_upload_url' );
	if ( $url ) {
		printf( '<p><strong>%s</strong> <a href="%s" target="_blank" rel="noopener">%s</a></p>', esc_html__( 'Uploaded file:', 'woocommerce' ), esc_url( $url ), esc_html( wp_basename( $url ) ) );
	}
}

function perfectpixel_checkout_upload_email( $order, $sent_to_admin ) {
